/* Lightweight SheetJS-compatible subset for this extension popup.
 * Exposes XLSX.read(arrayBuffer, {type:'array'}) and XLSX.utils.sheet_to_json(...).
 */
(function attachXLSX(global) {
  const decoder = new TextDecoder();

  function u16(view, off) { return view.getUint16(off, true); }
  function u32(view, off) { return view.getUint32(off, true); }

  async function inflateRaw(data) {
    const ds = new DecompressionStream('deflate-raw');
    const writer = ds.writable.getWriter();
    await writer.write(data);
    await writer.close();
    return new Uint8Array(await new Response(ds.readable).arrayBuffer());
  }

  async function unzip(arrayBuffer) {
    const view = new DataView(arrayBuffer);
    const bytes = new Uint8Array(arrayBuffer);

    let eocd = -1;
    for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65558); i -= 1) {
      if (u32(view, i) === 0x06054b50) { eocd = i; break; }
    }
    if (eocd < 0) throw new Error('Invalid XLSX (EOCD not found)');

    const centralSize = u32(view, eocd + 12);
    const centralOffset = u32(view, eocd + 16);
    const out = new Map();

    let p = centralOffset;
    const end = centralOffset + centralSize;

    while (p < end) {
      if (u32(view, p) !== 0x02014b50) throw new Error('Invalid XLSX central directory');

      const compression = u16(view, p + 10);
      const compressedSize = u32(view, p + 20);
      const nameLen = u16(view, p + 28);
      const extraLen = u16(view, p + 30);
      const commentLen = u16(view, p + 32);
      const localOffset = u32(view, p + 42);

      const nameStart = p + 46;
      const name = decoder.decode(bytes.slice(nameStart, nameStart + nameLen));

      if (u32(view, localOffset) !== 0x04034b50) throw new Error('Invalid XLSX local header');
      const localNameLen = u16(view, localOffset + 26);
      const localExtraLen = u16(view, localOffset + 28);
      const dataStart = localOffset + 30 + localNameLen + localExtraLen;
      const compData = bytes.slice(dataStart, dataStart + compressedSize);

      let content;
      if (compression === 0) content = compData;
      else if (compression === 8) content = await inflateRaw(compData);
      else throw new Error(`Unsupported compression method: ${compression}`);

      out.set(name, content);
      p += 46 + nameLen + extraLen + commentLen;
    }

    return out;
  }

  function parseXml(xml) {
    return new DOMParser().parseFromString(xml, 'application/xml');
  }

  function relTargetToPath(basePath, target) {
    if (target.startsWith('/')) return target.replace(/^\//, '');
    const base = basePath.split('/').slice(0, -1);
    for (const part of target.split('/')) {
      if (part === '.' || !part) continue;
      if (part === '..') base.pop();
      else base.push(part);
    }
    return base.join('/');
  }

  function findFirstSheetPath(entries) {
    const workbookPath = 'xl/workbook.xml';
    const relsPath = 'xl/_rels/workbook.xml.rels';

    const workbookXmlRaw = entries.get(workbookPath);
    if (!workbookXmlRaw) throw new Error('workbook.xml missing');

    const workbookDoc = parseXml(decoder.decode(workbookXmlRaw));
    const firstSheet = workbookDoc.getElementsByTagName('sheet')[0];
    const firstName = firstSheet?.getAttribute('name') || 'Sheet1';
    const relId = firstSheet?.getAttribute('r:id');

    let sheetPath = 'xl/worksheets/sheet1.xml';
    if (relId && entries.has(relsPath)) {
      const relsDoc = parseXml(decoder.decode(entries.get(relsPath)));
      const rels = relsDoc.getElementsByTagName('Relationship');
      for (const rel of rels) {
        if (rel.getAttribute('Id') === relId) {
          const target = rel.getAttribute('Target');
          if (target) {
            sheetPath = relTargetToPath(workbookPath, target);
            break;
          }
        }
      }
    }

    return { firstName, sheetPath };
  }

  function parseSharedStrings(entries) {
    const xmlRaw = entries.get('xl/sharedStrings.xml');
    if (!xmlRaw) return [];

    const doc = parseXml(decoder.decode(xmlRaw));
    const strings = [];
    for (const si of doc.getElementsByTagName('si')) {
      const ts = si.getElementsByTagName('t');
      let text = '';
      for (const t of ts) text += t.textContent || '';
      strings.push(text);
    }
    return strings;
  }

  function colIndex(ref) {
    const letters = (ref || 'A1').replace(/[0-9]/g, '');
    let out = 0;
    for (let i = 0; i < letters.length; i += 1) out = out * 26 + (letters.charCodeAt(i) - 64);
    return Math.max(0, out - 1);
  }

  function parseSheetRows(sheetXml, sharedStrings) {
    const doc = parseXml(sheetXml);
    const rows = [];

    for (const rowNode of doc.getElementsByTagName('row')) {
      const row = [];
      for (const c of rowNode.getElementsByTagName('c')) {
        const idx = colIndex(c.getAttribute('r'));
        const type = c.getAttribute('t');
        const v = c.getElementsByTagName('v')[0]?.textContent || '';
        const inlineT = c.getElementsByTagName('is')[0]?.getElementsByTagName('t')[0]?.textContent || '';

        let value = v;
        if (type === 's') value = sharedStrings[Number(v)] || '';
        else if (type === 'inlineStr') value = inlineT;

        row[idx] = value;
      }
      rows.push(row);
    }

    return rows;
  }

  async function read(arrayBuffer, options = {}) {
    if (options.type !== 'array') throw new Error('Only { type: "array" } supported');

    const entries = await unzip(arrayBuffer);
    const { firstName, sheetPath } = findFirstSheetPath(entries);
    const sheetRaw = entries.get(sheetPath);
    if (!sheetRaw) throw new Error(`Sheet not found: ${sheetPath}`);

    const sharedStrings = parseSharedStrings(entries);
    const rows = parseSheetRows(decoder.decode(sheetRaw), sharedStrings);

    return {
      SheetNames: [firstName],
      Sheets: {
        [firstName]: { __rows: rows }
      }
    };
  }

  const utils = {
    sheet_to_json(sheet, config = {}) {
      const rows = sheet?.__rows || [];
      if (config.header === 1) return rows;
      return rows.map((r) => ({ A: r[0] }));
    }
  };

  global.XLSX = { read, utils };
})(self);
